1f2937" stroke-width="2"/></g><circle cx="58" cy="54" r="6" fill="#1f2937"/><line x1="40" y1="14" x2="40" y2="40" stroke="#1f2937" stroke-width="2.2"/></svg>$q$, $q$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 80 80" width="80" height="80"><line x1="14" y1="26" x2="66" y2="26" stroke="#1f2937" stroke-width="2.2"/><rect x="16" y="46" width="14" height="14" fill="#9ca3af" stroke="#1f2937" stroke-width="2"/><circle cx="58" cy="54" r="6" fill="#1f2937"/><line x1="40" y1="14" x2="40" y2="40" stroke="#1f2937" stroke-width="2.2"/></svg>$q$, $q$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 80 80" width="80" height="80"><line x1="14" y1="26" x2="66" y2="26" stroke="#1f2937" stroke-width="2.2"/><rect x="16" y="46" width="14" height="14" fill="#9ca3af" stroke="#1f2937" stroke-width="2"/><circle cx="58" cy="54" r="6" fill="#1f2937"/></svg>$q$, $q$D$q$, $q$Everything from both figures appears, in exactly the same place and the same way round.$q$
     WHERE NOT EXISTS (SELECT 1 FROM public."mockTestGsQuestion"
                        WHERE "testId" = v_test AND "setNo" = 2 AND "subject" = 'NON_VERBAL' AND "questionOrder" = 23);
    INSERT INTO public."mockTestGsQuestion" ("testId", "setNo", "subject", "part", "compId", "questionOrder", "topic", "subTopic", "typeOfQuestion", "quest", "stemFormat", "stemFigure", "optionFormat", "optionA", "optionB", "optionC", "optionD", "optionE", "correctAnswer", "explanation")
    SELECT v_test, 2, $q$NON_VERBAL$q$, 3, NULL, 24, $q$Folding$q$, $q$Fold over$q$, $q$paper folding$q$, $q$The paper is see-through. It is folded along the dashed line so that the left half lies on top of the right half. What does it look like?$q$, $q$svg$q$, $q$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 90 90" width="90" height="90"><g transform="translate(5,5)"><rect x="0" y="0" width="80" height="80" rx="6" fill="#ffffff" stroke="#9ca3af" stroke-width="1.5"/><rect x="8" y="8" width="64" height="64" fill="#ffffff" stroke="#1f2937" stroke-width="2"/><line x1="40" y1="4" x2="40" y2="76" stroke="#1f2937" stroke-width="2" stroke-dasharray="5,4"/><circle cx="26" cy="22" r="7" fill="#9ca3af" stroke="#1f2937" stroke-width="1.5"/><rect x="12" y="44" width="10" height="18" fill="#1f2937"/><line x1="16" y1="66" x2="36" y2="66" stroke="#1f2937" stroke-width="3"/></g></svg>$q$, $q$svg$q$, $q$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 80 80" width="80" height="80"><rect x="8" y="8" width="64" height="64" fill="#ffffff" stroke="#1f2937" stroke-width="2"/><line x1="40" y1="4" x2="40" y2="76" stroke="#1f2937" stroke-width="2" stroke-dasharray="5,4"/><circle cx="26" cy="22" r="7" fill="#9ca3af" stroke="#1f2937" stroke-width="1.5"/><rect x="12" y="44" width="10" height="18" fill="#1f2937"/><line x1="16" y1="66" x2="36" y2="66" stroke="#1f2937" stroke-width="3"/><g transform="translate(80,0) scale(-1,1)"><circle cx="26" cy="22" r="7" fill="#9ca3af" stroke="#1f2937" stroke-width="1.5"/><rect x="12" y="44" width="10" height="18" fill="#1f2937"/><line x1="16" y1="66" x2="36" y2="66" stroke="#1f2937" stroke-width="3"/></g></svg>$q$, $q$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 80 80" width="80" height="80"><rect x="40" y="8" width="32" height="64" fill="#e5e7eb" stroke="#1f2937" stroke-width="2"/><g transform="translate(80,0) scale(-1,1)"><rect x="12" y="44" width="10" height="18" fill="#1f2937"/><line x1="16" y1="66" x2="36" y2="66" stroke="#1f2937" stroke-width="3"/></g></svg>$q$, $q$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 80 80" width="80" height="80"><rect x="40" y="8" width="32" height="64" fill="#e5e7eb" stroke="#1f2937" stroke-width="2"/><g transform="translate(0,80) scale(1,-1)"><g transform="translate(80,0) scale(-1,1)"><circle cx="26" cy="22" r="7" fill="#9ca3af" stroke="#1f2937" stroke-width="1.5"/><rect x="12" y="44" width="10" height="18" fill="#1f2937"/><line x1="16" y1="66" x2="36" y2="66" stroke="#1f2937" stroke-width="3"/></g></g></svg>$q$, $q$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 80 80" width="80" height="80"><rect x="40" y="8" width="32" height="64" fill="#e5e7eb" stroke="#1f2937" stroke-width="2"/><g transform="translate(32,0)"><circle cx="26" cy="22" r="7" fill="#9ca3af" stroke="#1f2937" stroke-width="1.5"/><rect x="12" y="44" width="10" height="18" fill="#1f2937"/><line x1="16" y1="66" x2="36" y2="66" stroke="#1f2937" stroke-width="3"/></g></svg>$q$, $q$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 80 80" width="80" height="80"><rect x="40" y="8" width="32" height="64" fill="#e5e7eb" stroke="#1f2937" stroke-width="2"/><g transform="translate(80,0) scale(-1,1)"><circle cx="26" cy="22" r="7" fill="#9ca3af" stroke="#1f2937" stroke-width="1.5"/><rect x="12" y="44" width="10" height="18" fill="#1f2937"/><line x1="16" y1="66" x2="36" y2="66" stroke="#1f2937" stroke-width="3"/></g></svg>$q$, $q$E$q$, $q$Folding works like a mirror: every mark lands the same distance from the fold, on the other side.$q$
     WHERE NOT EXISTS (SELECT 1 FROM public."mockTestGsQuestion"
                        WHERE "testId" = v_test AND "setNo" = 2 AND "subject" = 'NON_VERBAL' AND "questionOrder" = 24);

    RAISE NOTICE 'Mock Test 1 (paper id %): Non-Verbal questions 21-24 present in both sets.', v_test;
END
$do$;

